"""Shared editorial components for public-facing local pages."""
import news,seo
from urllib.parse import urlencode

def city(m=''):
 return next((x['name'] for x in news.read('municipalities') if x['slug']==m),'provincie Utrecht')
def breadcrumb(parts):
 return '<nav class="breadcrumbs" aria-label="Kruimelpad">'+''.join(('<span aria-current="page">'+news.e(label)+'</span>' if i==len(parts)-1 else '<a href="'+news.e(path)+'">'+news.e(label)+'</a><span aria-hidden="true">/</span>') for i,(label,path) in enumerate(parts))+'</nav>'
def heading(m,category,total,period,q=''):
 label=('Zoekresultaten voor “'+q+'”') if q else (news.CATEGORIES.get(category,'')+' in '+city(m) if category else 'Het nieuws uit '+city(m))
 return '<header class="edition-heading"><div><p class="eyebrow">'+('UIT HET ARCHIEF' if period=='archive' else 'DICHTBIJ EN VAN BELANG' if period=='all' else 'DICHTBIJ EN VAN BELANG')+'</p><h2>'+news.e(label)+'</h2></div><div><a href="/nieuws/dossiers">Volg een dossier ›</a></div></header>'
def city_links(m=''):
 place=city(m);root=news.BASE+('/'+m if m else '')
 return '<section class="local-discover"><div><p class="eyebrow">MEER UIT '+news.e(place.upper())+'</p><h2>Jouw omgeving, op één plek.</h2></div><div class="discover-links"><a href="'+root+'"><strong>Het lokale nieuws</strong><span>Besluiten, veiligheid en bereikbaarheid ›</span></a><a href="'+seo.agenda_path(m)+'"><strong>De gemeenteagenda</strong><span>Activiteiten uit PITO, dichtbij jou ›</span></a><a href="'+seo.agenda_path(m,'vandaag')+'"><strong>Vandaag te doen</strong><span>Bekijk wat er in de agenda staat ›</span></a><a href="'+root+'?weergave=community"><strong>Verhalen uit de buurt</strong><span>Van bewoners en lokale initiatieven ›</span></a></div></section>'
def share_tools(a):
 return '<div class="article-tools"><span>'+str(max(1,round(len(a['body'].split())/200)))+' min leestijd</span><button type="button" data-copy-link>Kopieer link</button><button type="button" data-share hidden>Deel artikel</button><span class="share-status" role="status" aria-live="polite"></span></div>'
def trustbar():
 return '<div class="editorial-trust"><span>Nieuws met een bron</span><a href="/nieuws/over-de-redactie">Zo werkt onze redactie</a><a href="/nieuws/bronnen">Onze bronnen</a><a href="/nieuws/selectie">Waarom dit nieuws?</a></div>'
def about():
 body=breadcrumb([('PITO','/'),('Nieuws',news.BASE),('Over de redactie','/nieuws/over-de-redactie')])+'<section class="section editorial-about"><p class="eyebrow">PITO NIEUWS</p><h1>Dichtbij. Duidelijk.<br>Controleerbaar.</h1><p class="standfirst">PITO verzamelt wat inwoners helpt hun omgeving te begrijpen: van een besluit in de gemeenteraad tot een afsluiting op jouw route.</p><div class="editorial-principles"><section><span>01</span><h2>Een bron bij elk verhaal</h2><p>We linken naar de oorspronkelijke publicatie. Een eigen samenvatting legt uit wat er verandert, voor wie en wanneer.</p></section><section><span>02</span><h2>Een besluit is geen voorstel</h2><p>Raadsagenda’s, plannen en vastgestelde besluiten krijgen een eigen status. De brondatum is niet automatisch onze publicatiedatum.</p></section><section><span>03</span><h2>Controle vóór publicatie</h2><p>AI kan helpen bij signalering en verwerking. Een redacteur controleert feiten, lokale relevantie, privacy en rechten voordat een artikel openbaar gaat.</p></section><section><span>04</span><h2>Herkenbare afzenders</h2><p>Communitybijdragen krijgen de naam van de schrijver. Reclame staat herkenbaar los van de redactie. Een partner koopt geen plek in de nieuwsrangschikking.</p></section></div><div class="sourcebox"><h2>Over deze lokale editie</h2><p>Dit is een ontwikkelomgeving. De zichtbare nieuwsberichten zijn redactieconcepten en het archief is nog niet volledig. De agenda toont pas actuele activiteiten zodra de PITO-bron is aangesloten. Deze website is niet openbaar gepubliceerd.</p><p>Bij een onjuistheid: gebruik de oorspronkelijke bron en leg de correctie vast via de <a href="/nieuws/redactie">lokale redactieomgeving</a>. Het openbare correctie- en contactproces moet vóór lancering worden ingericht.</p></div><a class="button" href="/nieuws/meedoen">Help mee als lokale redacteur</a></section>'
 return news.layout('Over de redactie',body,'/nieuws/over-de-redactie','De redactionele werkwijze van PITO Nieuws: bronnen, feitencontrole, community en herkenbare advertenties.')
